INSERT INTO "chat_snippets" ("key", "title", "body", "quick_replies", "trigger_label", "sort_order") VALUES
('goal_organize', 'Objetivo: organizar o mês', E'Boa escolha! Organizar o mês é o primeiro passo para o dinheiro render mais. 💜 Eu categorizo tudo e te mostro, de forma clara, para onde vai cada real.\n\nPara começar: **quer cadastrar sua primeira conta ou cartão agora?** Leva menos de um minuto.', '["Cadastrar agora"]', 'Organizar meu mês', 10),
('goal_reserve', 'Objetivo: reserva', E'Que ótimo objetivo! Uma reserva traz uma tranquilidade enorme. 💜 Eu te ajudo a separar um valor por mês sem sufocar o orçamento.\n\nPara começar: **quer cadastrar sua primeira conta ou cartão agora?** Leva menos de um minuto.', '["Cadastrar agora"]', 'Juntar uma reserva', 11),
('goal_debt', 'Objetivo: quitar dívidas', E'Vamos juntos nessa. 💜 Sair das dívidas é questão de método, não de culpa: eu te ajudo a enxergar para onde o dinheiro vai e a abrir espaço no mês.\n\nPara começar: **quer cadastrar sua primeira conta ou cartão agora?** Leva menos de um minuto.', '["Cadastrar agora"]', 'Quitar dívidas', 12),
('goal_dream', 'Objetivo: realizar um sonho', E'Que bom ter um sonho para planejar! 💜 Com um plano simples, dá para chegar lá no seu ritmo, e eu te acompanho no caminho.\n\nPara começar: **quer cadastrar sua primeira conta ou cartão agora?** Leva menos de um minuto.', '["Cadastrar agora"]', 'Realizar um sonho', 13),
('goal_understand', 'Objetivo: entender para onde vai o dinheiro', E'Perfeito: saber para onde o dinheiro vai é o que mais muda o jogo. 💜 Eu categorizo tudo e mostro de um jeito fácil de entender.\n\nPara começar: **quer cadastrar sua primeira conta ou cartão agora?** Leva menos de um minuto.', '["Cadastrar agora"]', 'Entender para onde vai meu dinheiro', 14),
('account_offer', 'Abrir o cadastro da primeira conta', E'Perfeito! Preencha a folha abaixo com o banco ou cartão. O nome do titular me ajuda a reconhecer transferências entre as suas contas.', '[]', 'Cadastrar agora', 15);
